const context = $json || {};
const base64Image = (context.provided_image_base64 || '').toString().trim();
if (!base64Image) {
  throw new Error('No se proporciono imagen base64 para usar.');
}
const extension = (context.provided_image_format || context.image_format || 'png').replace(/\./g, '').toLowerCase();
const fileName = `draft-${context.draft_id || 'unknown'}-${Date.now()}.${extension}`;

const visualPrompt = (context.provided_visual_prompt || context.visual_prompt || '').toString().trim();
const altCandidate = (context.provided_alt_text || context.alt_text || '').toString().trim();
const fallbackAlt = context.meta_description ? context.meta_description.slice(0, 140) : `Imagen ilustrativa de ${context.article_title || context.idea_title || 'articulo'}`;
const altText = altCandidate || fallbackAlt;

return [{
  json: {
    ...context,
    llm_raw_output: null,
    visual_prompt: visualPrompt || context.visual_prompt || '',
    alt_text: altText,
    llm_tokens_used: null,
    image_format: extension,
    image_file_name: fileName,
    image_base64: base64Image,
    preview_image_data_url: `data:image/${extension};base64,${base64Image}`,
    upload_performed: false
  },
  binary: {
    data: {
      data: base64Image,
      mimeType: `image/${extension}`,
      fileName
    }
  }
}];

const context = $json || {};
const extension = context.image_format || 'png';
const dataUrl = context.preview_image_data_url || (context.image_base64 ? `data:image/${extension};base64,${context.image_base64}` : null);

return [{
  json: {
    ...context,
    preview_image_data_url: dataUrl,
    preview_image_base64: context.image_base64 || null,
    saved_image_url: dataUrl,
    saved_image_alt: context.alt_text || null,
    image_url: dataUrl,
    wordpress_media_id: null,
    wordpress_media_url: null,
    upload_performed: false
  }
}];

function toArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.map(String).map((v) => v.trim()).filter(Boolean);
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed.map(String).map((v) => v.trim()).filter(Boolean);
    } catch (_) {}
    return trimmed.split(/,|\n|;|\|/).map((part) => part.trim()).filter(Boolean);
  }
  return [];
}

const env = (name) => (typeof $env === 'function' ? $env(name) : undefined);

const requestBody = $items('Webhook1')[0]?.json?.body ?? {};
const context = $json ?? {};

const keywordsSec = toArray(context.keywords_secundarias);
const tags = toArray(context.tags);
const keywords = [context.keyword_principal, ...keywordsSec]
  .map((value) => (value || '').toString().trim())
  .filter(Boolean)
  .filter((value, index, self) => self.indexOf(value) === index);

const article = (context.content_markdown || '')
  .replace(/\r/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const maxLength = Number(requestBody.article_max_chars) || 8000;
const excerpt = article.length > maxLength ? article.slice(0, maxLength) : article;

const openAiModel = requestBody.openai_model || env('OPENAI_DEFAULT_MODEL') || 'gpt-4o-mini';
const geminiModel = requestBody.gemini_model || env('GEMINI_DEFAULT_MODEL') || 'gemini-1.5-flash-latest';

const uploadToWordpress = requestBody.upload_to_wordpress === true;
const providedImageBase64 = (requestBody.preview_image_base64 || requestBody.image_base64 || '').toString().trim();
const providedImageFormatRaw = (requestBody.preview_image_format || requestBody.image_format || '').toString().trim();
const providedVisualPrompt = requestBody.preview_visual_prompt || requestBody.visual_prompt || requestBody.image_prompt || null;
const providedAltText = requestBody.preview_alt_text || requestBody.alt_text || null;
const skipGeneration = Boolean(providedImageBase64);

const resolvedImageFormat = (providedImageFormatRaw || requestBody.image_format || context.image_format || 'png')
  .replace(/\./g, '')
  .toLowerCase();

let wordpressEndpoint = null;
let wordpressAuthHeader = null;
let wordpressNonce = null;
const wordpressTitle = requestBody.wordpress_title || context.meta_title || context.article_title || context.idea_title || '';
const wordpressUpdateAlt = requestBody.wordpress_update_alt !== false;

if (uploadToWordpress) {
  const endpointRaw = (requestBody.wordpress_endpoint || env('WORDPRESS_MEDIA_ENDPOINT') || '').toString().trim();
  if (!endpointRaw) {
    throw new Error('Se requiere "wordpress_endpoint" en la peticion o la variable WORDPRESS_MEDIA_ENDPOINT.');
  }
  wordpressEndpoint = endpointRaw.replace(/\/?$/, '');
  wordpressAuthHeader = requestBody.wordpress_auth_header || env('WORDPRESS_AUTH_HEADER') || null;
  wordpressNonce = requestBody.wordpress_nonce || env('WORDPRESS_NONCE') || null;
}

const instruction = [
  'You are a senior visual prompt designer for blog marketing teams.',
  'Craft a rich, specific English prompt (max 4 sentences) for an AI image model focusing on a single scene.',
  'Highlight concrete subjects, environment, lighting, mood, and artistic style. Avoid references to text or typography.'
].join('\n');

const extra = [
  'Also produce a concise alt text in Spanish (max 140 characters) describing the resulting image for SEO.',
  'Return only valid JSON using this schema: { "visual_prompt": string, "alt_text": string }.'
].join('\n');

const userContent = [
  `Article title: ${context.title || context.meta_title || context.idea_title || ''}`,
  context.meta_description ? `Meta description: ${context.meta_description}` : null,
  keywords.length ? `Main keywords: ${keywords.join(', ')}` : null,
  tags.length ? `Tags: ${tags.join(', ')}` : null,
  context.word_count ? `Word count: ${context.word_count}` : null,
  `Article excerpt (Spanish):\n${excerpt}`
].filter(Boolean).join('\n\n');

const promptPayload = `${instruction}\n\n${extra}\n\n${userContent}`;

return [{
  json: {
    draft_id: context.draft_id,
    idea_id: context.idea_id,
    keyword_cluster_id: context.keyword_cluster_id,
    cluster_name: context.cluster_name,
    idea_title: context.idea_title,
    article_title: context.title,
    meta_title: context.meta_title,
    meta_description: context.meta_description,
    main_keywords: keywords,
    tags,
    article_text: excerpt,
    request_body: {
      ...requestBody,
      upload_to_wordpress: uploadToWordpress
    },
    openai_model: openAiModel,
    gemini_model: 'gemini-1.5-flash-latest',
    image_format: resolvedImageFormat,
    upload_to_wordpress: uploadToWordpress,
    skip_generation: skipGeneration,
    provided_image_base64: providedImageBase64 || null,
    provided_image_format: providedImageFormatRaw || null,
    provided_visual_prompt: providedVisualPrompt || null,
    provided_alt_text: providedAltText || null,
    wordpress_endpoint: wordpressEndpoint,
    wordpress_auth_header: wordpressAuthHeader,
    wordpress_nonce: wordpressNonce,
    wordpress_title: wordpressTitle,
    wordpress_update_alt: wordpressUpdateAlt,
    prompt_payload: promptPayload,
    start_time: new Date().toISOString(),
    start_ts_ms: Date.now()
  }
}];

const idx = $itemIndex;
const context = $items('Preparar Contexto Imagen1', 0)[idx]?.json || {};

const textFromOutput = ($json.output_text || []).join('\n').trim();

const textFromContent = ($json.output || [])
  .flatMap((entry) => (entry.content || []))
  .map((part) => (part.text || '').trim())
  .filter(Boolean)
  .join('\n')
  .trim();

const rawOutput = textFromOutput || textFromContent;

if (!rawOutput) {
  const status = $json.status || 'desconocido';
  const reason = $json.incomplete_details?.reason || 'sin motivo informado';
  throw new Error(`OpenAI no devolvio texto. Estado: ${status}, motivo: ${reason}.`);
}

let parsed;
try {
  parsed = JSON.parse(rawOutput);
} catch (_) {
  parsed = { visual_prompt: rawOutput };
}

const visualPrompt = (parsed.visual_prompt || parsed.prompt || rawOutput).toString().trim();
const altTextCandidate = (parsed.alt_text || parsed.altText || '').toString().trim();
const fallbackAlt = context.meta_description ? context.meta_description.slice(0, 140)
  : `Imagen ilustrativa de ${context.article_title || context.idea_title || 'articulo'}`;

return [{
  json: {
    ...context,
    llm_raw_output: rawOutput,
    visual_prompt: visualPrompt,
    alt_text: altTextCandidate || fallbackAlt,
    llm_tokens_used: $json.usage?.total_tokens || $json.usage?.totalTokens || null
  }
}];

// En modo filesystem, usar helpers de n8n
const item = $input.item;

if (!item.binary || !item.binary.data) {
  return { 
    ...$json, 
    _skip: true, 
    _skip_reason: 'no_binary_in_item'
  };
}

// Usar el helper para obtener el buffer
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const imgB64 = binaryData.toString('base64');

const fileName = `img_${$json.draft_id || Date.now()}.png`;
const extension = $json.image_format || 'png';

return {
  ...$json,
  image_file_name: fileName,
  image_format: extension,
  image_base64: imgB64,
  preview_image_data_url: `data:image/${extension};base64,${imgB64}`,
  preview_image_base64: imgB64
};

const idx = $itemIndex;
const wpContext = $items('Combinar Datos WordPress1', 0)?.[idx]?.json || {};
const updatedDraft = $json || {};
const imageUrl = updatedDraft.featured_image_url || wpContext.image_url || wpContext.wordpress_media_url || null;
const altText = updatedDraft.featured_image_alt || wpContext.alt_text || null;

return [{
  json: {
    ...wpContext,
    updated_draft: updatedDraft,
    saved_image_url: imageUrl,
    saved_image_alt: altText,
    image_url: imageUrl,
    wordpress_media_id: wpContext.wordpress_media_id || updatedDraft.wordpress_media_id || null,
    wordpress_media_url: wpContext.wordpress_media_url || null,
    upload_performed: true
  }
}];

const context = $json || {};
const endTime = new Date();
const durationMs = Math.max(0, Date.now() - (context.start_ts_ms || Date.now()));

const jobLog = {
  job_name: 'SEO - 12 Generacion de Imagenes',
  job_type: 'image_generation',
  status: 'success',
  related_keyword_id: context.keyword_cluster_id || null,
  related_idea_id: context.idea_id || null,
  related_draft_id: context.draft_id || null,
  started_at: context.start_time || endTime.toISOString(),
  completed_at: endTime.toISOString(),
  duration_ms: durationMs,
  input_data: {
    article_title: context.article_title || context.meta_title,
    main_keywords: context.main_keywords || [],
    upload_to_wordpress: context.upload_to_wordpress || false,
    provided_image: Boolean(context.provided_image_base64)
  },
  output_data: {
    image_url: context.saved_image_url || context.image_url || null,
    alt_text: context.saved_image_alt || context.alt_text || null,
    visual_prompt: context.visual_prompt || null,
    upload_performed: context.upload_performed || false,
    wordpress_media_id: context.wordpress_media_id || null,
    preview_image_available: Boolean(context.preview_image_base64)
  }
};

return [{
  json: {
    ...context,
    job_log: jobLog
  }
}];

const context = $items('Preparar Job Log1', 0)[$itemIndex]?.json || {};
const jobLogRow = $json || {};

return [{
  json: {
    ...context,
    job_log_id: jobLogRow.id || null,
    job_log_created_at: jobLogRow.created_at || null
  }
}];

const items = $json.processed_items || [];
return [{
  json: {
    status: 'success',
    total_drafts_processed: items.length,
    total_images_created: items.filter((item) => item.upload_performed === true).length,
    drafts: items.map((item) => ({
      draft_id: item.draft_id,
      idea_id: item.idea_id,
      cluster_name: item.cluster_name,
      upload_performed: item.upload_performed === true,
      preview_image_data_url: item.preview_image_data_url || null,
      preview_image_base64: item.preview_image_base64 || null,
      image_format: item.image_format || null,
      alt_text: item.saved_image_alt || item.alt_text || null,
      visual_prompt: item.visual_prompt || null,
      image_url: item.saved_image_url || item.image_url || null,
      wordpress_media_id: item.wordpress_media_id || null,
      wordpress_media_url: item.wordpress_media_url || null,
      job_log_id: item.job_log_id || null
    })),
    generated_at: new Date().toISOString()
  }
}];

return [{
  json: {
    status: 'info',
    message: 'No hay drafts pendientes de imagen.',
    generated_at: new Date().toISOString()
  }
}];

const idx = $itemIndex;

// Intenta traer el json de un nodo si existe en esta ejecución
const fromNode = (name) => {
  try { return $items(name, 0)[idx]?.json ?? null; }
  catch (e) { return null; }
};

// Prioridades de “contexto” según tus ramas
const context =
  fromNode('Convertir Imagen a Binario1') ||     // rama que convierte base64→binario
  fromNode('Usar Imagen Proporcionada1') ||      // rama cuando subes una imagen ya dada
  fromNode('Preparar Contexto Imagen1') ||       // cualquier nodo donde tengas los metadatos
  {};                                            // fallback

// Respuesta directa del upload a WP (input del Code)
const response = $json ?? {};

const mediaId   = response.id ?? response.data?.id ?? null;
const sourceUrl = response.source_url
               ?? response.guid?.rendered
               ?? response.media_details?.sizes?.full?.source_url
               ?? null;

if (!sourceUrl) {
  throw new Error('WordPress no devolvió source_url al subir la imagen.');
}

return [{
  json: {
    ...context,
    wordpress_response: response,
    wordpress_media_id: mediaId,
    wordpress_media_url: sourceUrl,
    image_url: sourceUrl
  }
}];

const body = $json.body || {};

const clauses = [
  "COALESCE(d.content_markdown, '') <> ''"
];

if (!body.force) {
  clauses.push("(d.featured_image_url IS NULL OR d.featured_image_url = '')");
}

if (!body.include_published) {
  clauses.push("d.status IN ('draft','review','approved')");
}

if (body.draft_id) {
  clauses.push(`d.id = '${String(body.draft_id).replace(/'/g, "''")}'`);
}

if (body.idea_id) {
  clauses.push(`d.idea_id = '${String(body.idea_id).replace(/'/g, "''")}'`);
}

if (body.keyword_cluster_id) {
  clauses.push(`d.keyword_cluster_id = '${String(body.keyword_cluster_id).replace(/'/g, "''")}'`);
}

if (body.project_name) {
  clauses.push(`k.project_name = '${String(body.project_name).replace(/'/g, "''")}'`);
}

const limit = Number(body.limit) || 3;

return [{
  json: {
    whereClause: clauses.join('\n  AND '),
    limit
  }
}];
